usage:
import { TabsUnderlineGlide } from "@/components/design-for-ai/tabs-underline-glide";

<TabsUnderlineGlide
  label="Project sections"
  defaultValue="overview"
  items={[
    { value: "overview", label: "Overview", content: <Overview /> },
    { value: "deployments", label: "Deployments", count: 24, content: <Deployments /> },
    { value: "settings", label: "Settings", content: <Settings /> },
  ]}
  onValueChange={(section) => router.replace(`?tab=${section}`)}
/>

// Heavy panels: open on Enter instead of on arrow focus
<TabsUnderlineGlide activation="manual" indicator="pill" theme="light" items={sections} />
